import pyomo.environ as pyo

DATA = {
    "food_set": ["Apple", "Banana"],
    "nutrient_set": ["VitaminC", "Fiber"],
    "food_cost": [2.0, 1.5],
    "min_food_amount": [0, 0],
    "max_food_amount": [10, 10],
    "min_nutrient_amount": [50, 30],
    "max_nutrient_amount": [100, 60],
    # nutrient_amount[food][nutrient]
    "nutrient_amount": [[10, 5], [5, 10]],
}


def build_model(data=None):
    d = data or DATA

    foods = d["food_set"]
    nutrients = d["nutrient_set"]

    cost = {f: d["food_cost"][k] for k, f in enumerate(foods)}
    min_food = {f: d["min_food_amount"][k] for k, f in enumerate(foods)}
    max_food = {f: d["max_food_amount"][k] for k, f in enumerate(foods)}
    min_nut = {n: d["min_nutrient_amount"][k] for k, n in enumerate(nutrients)}
    max_nut = {n: d["max_nutrient_amount"][k] for k, n in enumerate(nutrients)}
    # content[(food, nutrient)]
    content = {
        (f, n): d["nutrient_amount"][kf][kn]
        for kf, f in enumerate(foods)
        for kn, n in enumerate(nutrients)
    }

    model = pyo.ConcreteModel()

    model.Foods = pyo.Set(initialize=foods, ordered=True)
    model.Nutrients = pyo.Set(initialize=nutrients, ordered=True)

    # Decision variable: amount of each food to buy
    def buy_bounds(m, j):
        return (min_food[j], max_food[j])

    model.buy = pyo.Var(
        model.Foods,
        domain=pyo.NonNegativeReals,
        bounds=buy_bounds,
    )

    # Objective: minimize total cost
    def obj_rule(m):
        return sum(cost[j] * m.buy[j] for j in m.Foods)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Lower nutrient requirement
    def min_nutrient_rule(m, i):
        return sum(content[(j, i)] * m.buy[j] for j in m.Foods) >= min_nut[i]

    model.min_nutrient_constraint = pyo.Constraint(
        model.Nutrients, rule=min_nutrient_rule
    )

    # Upper nutrient allowance
    def max_nutrient_rule(m, i):
        return sum(content[(j, i)] * m.buy[j] for j in m.Foods) <= max_nut[i]

    model.max_nutrient_constraint = pyo.Constraint(
        model.Nutrients, rule=max_nutrient_rule
    )

    return model


